func HullConfigLoadBodyRetain(r *TableRetainReader, value *HullConfig) bool {
	HullConfigReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x7f69d4b5288ba9cf: // health
			if kind != 10 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(4) {
				r.Report.Malformed = true
				return false
			}
			{
				b := r.Get32()
				if b&0x7f800000 == 0x7f800000 {
					tableNonFiniteFloat(&r.Report.NonFiniteFloat, "HullConfig.health")
				} else {
					v := math.Float32frombits(b)
					value.Health = v
				}
			}
		case 0x1f3757a2ce7b0ab1: // mass
			if kind != 10 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(4) {
				r.Report.Malformed = true
				return false
			}
			{
				b := r.Get32()
				if b&0x7f800000 == 0x7f800000 {
					tableNonFiniteFloat(&r.Report.NonFiniteFloat, "HullConfig.mass")
				} else {
					v := math.Float32frombits(b)
					value.Mass = v
				}
			}
		case 0x84f8260bc283608c: // turrets
			if kind != 16 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					for range count {
						keyRef, ok := sub.Leb()
						if !ok {
							r.Report.Malformed = true
							break
						}
						key, ok := sub.Resolve(keyRef)
						if !ok {
							r.Report.Malformed = true
							break
						}
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						var slot Weapon
						if !slot.TableEnumValue(key) {
							r.Report.Unknown++
							if r.Retain != nil {
								r.Report.RetainLost++
							}
							continue
						}
						elem.Path = r.Path.step(2, uint32(int(slot)-1))
						TurretConfigLoadBodyRetain(&elem, &value.Turrets[int(slot)-1])
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							TurretConfigReset(&value.Turrets[int(slot)-1])
						}
					}
				}
			}
		default:
			r.Report.Unknown++
			if !r.capture(fieldID, kind, "HullConfig") {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// KeyedConfigReset restores KeyedConfig's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func KeyedConfigReset(value *KeyedConfig) {
	for i := range value.Teams {
		TeamConfigReset(&value.Teams[i])
	}
	for i := range value.Hulls {
		HullConfigReset(&value.Hulls[i])
	}
	ScoreBoardReset(&value.Scores)
}

