func KeyedConfigLoadBodyRetain(r *TableRetainReader, value *KeyedConfig) bool {
	KeyedConfigReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0xbaaeb048a5a8fa6d: // teams
			if kind != 16 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					for range count {
						keyRef, ok := sub.Leb()
						if !ok {
							r.Report.Malformed = true
							break
						}
						key, ok := sub.Resolve(keyRef)
						if !ok {
							r.Report.Malformed = true
							break
						}
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						var slot Team
						if !slot.TableEnumValue(key) {
							r.Report.Unknown++
							if r.Retain != nil {
								r.Report.RetainLost++
							}
							continue
						}
						elem.Path = r.Path.step(0, uint32(int(slot)-1))
						TeamConfigLoadBodyRetain(&elem, &value.Teams[int(slot)-1])
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							TeamConfigReset(&value.Teams[int(slot)-1])
						}
					}
				}
			}
		case 0xce0ac3c25694d8ff: // hulls
			if kind != 16 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					for range count {
						keyRef, ok := sub.Leb()
						if !ok {
							r.Report.Malformed = true
							break
						}
						key, ok := sub.Resolve(keyRef)
						if !ok {
							r.Report.Malformed = true
							break
						}
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						var slot Hull
						if !slot.TableEnumValue(key) {
							r.Report.Unknown++
							if r.Retain != nil {
								r.Report.RetainLost++
							}
							continue
						}
						elem.Path = r.Path.step(1, uint32(int(slot)-1))
						HullConfigLoadBodyRetain(&elem, &value.Hulls[int(slot)-1])
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							HullConfigReset(&value.Hulls[int(slot)-1])
						}
					}
				}
			}
		case 0x01986b0b27400fb2: // scores
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			sub.Path = r.Path.step(2, uint32(0))
			ScoreBoardLoadBodyRetain(&sub, &value.Scores)
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				ScoreBoardReset(&value.Scores)
			}
		default:
			r.Report.Unknown++
			if !r.capture(fieldID, kind, "KeyedConfig") {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// ScoreBoardReset restores ScoreBoard's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ScoreBoardReset(value *ScoreBoardRow) {
	clear(value.PerTeam[:])
}

func ScoreBoardMeasureBody(value *ScoreBoardRow, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ScoreBoardSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ScoreBoardMeasure(value *ScoreBoardRow) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ScoreBoardSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ScoreBoardMeasureReason(value *ScoreBoardRow) (int64, error) {
	size := ScoreBoardMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func ScoreBoardSaveBody(w *TableWriter, value *ScoreBoardRow) bool {
	if !ScoreBoardSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
