// KeyedConfigFixedPlanMax is the plan capacity every layout this build reads needs:
// the largest entry count over the identity plan and every lineage plan
// (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5.2). A plan slice of this length never
// refuses plan_too_large for a layout the lineage holds.
var KeyedConfigFixedPlanMax = func() int32 {
	m := KeyedConfigFixedPlan.Count
	for _, lane := range KeyedConfigFixedLineagePlans {
		if lane.Count > m {
			m = lane.Count
		}
	}
	return m
}()

// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func KeyedConfigFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(KeyedConfigFixedLayout)) + count*KeyedConfigFixedRecordBytes
}

// KeyedConfigFixedSave is the fixed form's writer: it returns the bytes written, or -1 for a
// buffer too short or a value outside its declared contract (§3.1); see FixedSaveReason.
func KeyedConfigFixedSave(values []KeyedConfig, buffer []byte) int64 {
	need := KeyedConfigFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	for k := range values {
		if !KeyedConfigFixedCheckBody(&values[k]) {
			return -1
		}
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], KeyedConfigFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(KeyedConfigFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], KeyedConfigFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(KeyedConfigFixedLayout):]
	for k := range values {
		tableFixedPut64(at, KeyedConfigFixedHash)
		clear(at[8 : 8+KeyedConfigFixedBodyBytes])
		KeyedConfigFixedWriteBody(at[8:], &values[k])
		at = at[KeyedConfigFixedRecordBytes:]
	}
	return need
}

func KeyedConfigFixedSaveReason(values []KeyedConfig, buffer []byte) (int64, error) {
	if n := KeyedConfigFixedSave(values, buffer); n >= 0 {
		return n, nil
	}
	if int64(len(buffer)) < KeyedConfigFixedMeasure(int64(len(values))) {
		return -1, TableRefuseTruncated
	}
	return -1, TableRefuseInvalidValue
}

// KeyedConfigFixedLoad is the plain fixed-form read, and it is STRICT (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): -1 for
// every refusal of KeyedConfigFixedLoadTolerant and for a read whose report.Err() is not nil, with
// every value it had written reset. A supplied report receives THIS read's report.
func KeyedConfigFixedLoad(values []KeyedConfig, data []byte, plan []TableFixedEntry, report *TableReport) int64 {
	read := report
	if read == nil {
		read = &TableReport{}
	} else {
		*read = TableReport{}
	}
	n := KeyedConfigFixedLoadTolerant(values, data, plan, read)
	if n < 0 {
		return -1
	}
	if read.Err() != nil {
		for k := range n {
			KeyedConfigReset(&values[k])
		}
		return -1
	}
	return n
}

// KeyedConfigFixedLoadTolerant is the TOLERANT fixed-form read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): it keeps
